62: function strike(){if(!gameStarted||paused||dialogueLock||attackCooldown>0)return;attackCooldown=.42;const origin=player.position,dir=forward();let candidates=mode==='villain'?villainTargets.filter(a=>a.alive):enemies.filter(a=>a.alive);if(mode==='story'&&boss&&storyStage>=2&&boss.alive)candidates=[boss];let victim=null,best=3.25;for(const a of candidates){const dx=a.mesh.position.x-origin.x,dz=a.mesh.position.z-origin.z,d=Math.hypot(dx,dz),dot=d?((dx*dir.x+dz*dir.z)/d):1;if(d<best&&(dot>.15||d<1.3)){victim=a;best=d}}if(victim){const damage=stealth?28:18;victim.health-=damage;victim.alert=true;victim.mesh.rotation.y=Math.atan2(origin.x-victim.mesh.position.x,origin.z-victim.mesh.position.z);toast(stealth?'SILENT TAKEDOWN':'STRIKE · '+victim.name);if(victim.health<=0){victim.health=0;victim.alive=false;victim.mesh.visible=false;if(victim.type==='enemy'){gangDown++;if(gangDown===5)toast('GANG OPERATION DISRUPTED');progress()}if(mode==='villain'){toast('HERO DOWN');if(villainTargets.every(a=>!a.alive)){villainTargets.forEach(a=>{a.alive=true;a.health=100;a.mesh.visible=true});heroHealth=100;toast('HEROES RALLY — FIGHT ON')}}if(victim===boss)progress()}else if(victim===boss){$('#boss-fill').style.width=`${victim.health}%`;updateObjective()}}else if(mode==='story'){toast('NO THREAT IN RANGE')} }
