64: function enemiesThink(dt){const now=gameTime;for(const e of [...enemies,...villainTargets]){if(!e.alive||!e.mesh.visible)continue;const d=distance(e.mesh.position,player.position);const hidden=stealth&&mode!=='villain';if(d<13&&!hidden)e.alert=true;if(e.alert&&d>2.05){const dx=player.position.x-e.mesh.position.x,dz=player.position.z-e.mesh.position.z,len=Math.hypot(dx,dz)||1;e.mesh.position.x+=dx/len*dt*(mode==='villain'?2.4:2.1);e.mesh.position.z+=dz/len*dt*(mode==='villain'?2.4:2.1);e.mesh.rotation.y=Math.atan2(dx,dz)}else if(e.alert&&d<=2.05&&now-(e.lastHit||0)>1.05){e.lastHit=now;damageHero(mode==='villain'?10:8)}}}
